    fill2,extra2=divmod(remaining+1,320);v=run('over-byte-limit',dict(mode='synthetic',count='320',fill=str(fill2),extra=str(extra2)),3);check('byte limit typed refusal',v['reason']=='message_too_large')
    v=run('distinct-history',dict(mode='history',count='1',fill='0',extra='0'))
